     1→import { useState } from 'react';
     2→import { BEZIRK_PATHS, BL_BORDER_PATHS } from '../data/bezirkPaths';
     3→
     4→interface BezirkData {
     5→  bezirk_code: string;
     6→  participants: number;
     7→  reports: number;
     8→}
     9→
    10→interface Props {
    11→  data: BezirkData[];
    12→}
    13→
    14→// BL_BORDER_PATHS imported from generated data (same projection as BEZIRK_PATHS)
    15→
    16→const BL_NAMES: Record<string, string> = {
    17→  '01': 'Wien', '02': 'Salzburg', '03': 'Niederösterreich', '04': 'Burgenland',
    18→  '05': 'Oberösterreich', '06': 'Steiermark', '07': 'Tirol', '08': 'Kärnten',
    19→  '09': 'Vorarlberg',
    20→};
    21→
    22→function getHeatColor(value: number, max: number): string {
    23→  if (max === 0 || value === 0) return '#f3f4f6';
    24→  const t = Math.min(value / max, 1);
    25→  // Light blue (#c2d5ec) → Dark navy (#1e3a5f)
    26→  const r = Math.round(194 + (30 - 194) * t);
    27→  const g = Math.round(213 + (58 - 213) * t);
    28→  const b = Math.round(236 + (95 - 236) * t);
    29→  return `rgb(${r},${g},${b})`;
    30→}
    31→
    32→export default function AustriaBezirkMap({ data }: Props) {
    33→  const [tooltip, setTooltip] = useState<{
    34→    x: number;
    35→    y: number;
    36→    code: string;
    37→    name: string;
    38→    bundesland: string;
    39→    participants: number;
    40→    reports: number;
    41→  } | null>(null);
    42→
    43→  const dataMap = new Map(data.map((d) => [d.bezirk_code, d]));
    44→  const maxParticipants = Math.max(...data.map((d) => d.participants), 1);
    45→
    46→  const showTooltip = (
    47→    e: React.MouseEvent,
    48→    code: string,
    49→    labelX: number,
    50→    labelY: number,
    51→    participants: number,
    52→    reports: number,
    53→    name: string,
    54→    bundesland: string,
    55→  ) => {
    56→    const svg = e.currentTarget.closest('svg');
    57→    if (!svg) return;
    58→    const rect = svg.getBoundingClientRect();
    59→    const pt = svg.createSVGPoint();
    60→    pt.x = labelX;
    61→    pt.y = labelY;
    62→    const ctm = svg.getScreenCTM();
    63→    if (!ctm) return;
    64→    const screenPt = pt.matrixTransform(ctm);
    65→    setTooltip({
    66→      x: screenPt.x - rect.left,
    67→      y: screenPt.y - rect.top - 10,
    68→      code,
    69→      name,
    70→      bundesland,
    71→      participants,
    72→      reports,
    73→    });
    74→  };
    75→
    76→  return (
    77→    <div className="relative">
    78→      <svg
    79→        viewBox="-5 -10 630 335"
    80→        className="w-full h-auto"
    81→        preserveAspectRatio="xMidYMid meet"
    82→        role="img"
    83→        aria-label="Bezirks-Heatmap von Österreich"
    84→      >
    85→        {/* Bezirk polygons */}
    86→        {Object.entries(BEZIRK_PATHS).map(([code, { d, labelX, labelY, name, bundesland_code }]) => {
    87→          const bz = dataMap.get(code);
    88→          const participants = bz?.participants ?? 0;
    89→          const reports = bz?.reports ?? 0;
    90→          const fill = getHeatColor(participants, maxParticipants);
    91→          const blName = BL_NAMES[bundesland_code] || '';
    92→
    93→          return (
    94→            <path
    95→              key={code}
    96→              d={d}
    97→              fill={fill}
    98→              stroke="#ffffff"
    99→              strokeWidth="0.5"
   100→              className="transition-opacity hover:opacity-75 cursor-pointer"
   101→              onMouseEnter={(e) => showTooltip(e, code, labelX, labelY, participants, reports, name, blName)}
   102→              onMouseLeave={() => setTooltip(null)}
   103→            />
   104→          );
   105→        })}
   106→
   107→        {/* Bundesland borders overlay */}
   108→        {Object.values(BL_BORDER_PATHS).map((d, i) => (
   109→          <path
   110→            key={`bl-${i}`}
   111→            d={d}
   112→            fill="none"
   113→            stroke="#1e3a5f"
   114→            strokeWidth="1.5"
   115→            pointerEvents="none"
   116→          />
   117→        ))}
   118→
   119→        {/* Labels for all Bezirke */}
   120→        {Object.entries(BEZIRK_PATHS).map(([code, { labelX, labelY }]) => {
   121→          const bz = dataMap.get(code);
   122→          const hasData = bz && bz.participants > 0;
   123→          const isDark = hasData && bz.participants / maxParticipants > 0.5;
   124→          return (
   125→            <text
   126→              key={`label-${code}`}
   127→              x={labelX}
   128→              y={labelY}
   129→              textAnchor="middle"
   130→              dominantBaseline="central"
   131→              fontSize={hasData ? '7' : '6'}
   132→              fontWeight={hasData ? 'bold' : 'normal'}
   133→              fill={hasData ? (isDark ? '#ffffff' : '#1e3a5f') : '#9ca3af'}
   134→              pointerEvents="none"
   135→              stroke={isDark ? '#1e3a5f' : '#ffffff'}
   136→              strokeWidth={isDark ? '0.5' : hasData ? '1.5' : '1'}
   137→              paintOrder="stroke"
   138→            >
   139→              {code}
   140→            </text>
   141→          );
   142→        })}
   143→      </svg>
   144→
   145→      {/* Tooltip */}
   146→      {tooltip && (
   147→        <div
   148→          className="absolute bg-gray-900 text-white text-xs rounded px-2 py-1.5 pointer-events-none shadow-lg z-10 whitespace-nowrap"
   149→          style={{
   150→            left: tooltip.x,
   151→            top: tooltip.y,
   152→            transform: 'translate(-50%, -100%)',
   153→          }}
   154→        >
   155→          <div className="font-bold">{tooltip.code} — {tooltip.name}</div>
   156→          <div className="text-gray-300">{tooltip.bundesland}</div>
   157→          <div>Teilnehmer: {tooltip.participants}</div>
   158→          <div>Rapporte: {tooltip.reports}</div>
   159→        </div>
   160→      )}
   161→
   162→      {/* Legend */}
   163→      <div className="flex items-center justify-center gap-2 mt-2 text-xs text-gray-500">
   164→        <span>0</span>
   165→        <div
   166→          className="h-3 w-32 rounded"
   167→          style={{
   168→            background: 'linear-gradient(to right, #c2d5ec, #1e3a5f)',
   169→          }}
   170→        />
   171→        <span>{maxParticipants}</span>
   172→        <span className="ml-1 text-gray-400">Teilnehmer</span>
   173→      </div>
   174→    </div>
   175→  );
   176→}
