   231→// projection, NOT Mercator. Analysis of the existing map shows:
   232→//   - X scale: 78.55 px/degree
   233→//   - Y scale: ~118 px/degree (linear)
   234→//   - Y/X ratio: ~1.50 (consistent with equirectangular at ~48°N)
   235→//
   236→// Calibration anchor: Wien center 16.37°E, 48.21°N → SVG (550, 97)
   237→//
   238→// X: x = lon * SX + OX
   239→//   SX = 78.55
   240→//   OX = 550 - 16.37 * 78.55 = -735.86
   241→//
   242→// Y: y = lat * SY + OY  (linear, negative because SVG Y increases downward)
   243→//   SY = -SX * 1.50 = -117.83  (Y/X ratio from existing map analysis)
   244→//   OY = 97 - 48.21 * (-117.83) = 97 + 5680.0 = 5777.0
   245→
   246→const SX = 78.55;
   247→const OX = -735.86;
   248→const SY = -117.83;
   249→const OY = 5777.0;
   250→
   251→function projectLon(lon) { return lon * SX + OX; }
   252→function projectLat(lat) { return lat * SY + OY; }
   253→
   254→function coordsToSvgPath(rings) {
   255→  return rings.map((ring, ri) => {
   256→    const parts = ring.map(([lon, lat], i) => {
   257→      const x = projectLon(lon);
   258→      const y = projectLat(lat);
   259→      const xr = Math.round(x * 100) / 100;
   260→      const yr = Math.round(y * 100) / 100;
   261→      return `${i === 0 ? 'M' : 'L'}${xr},${yr}`;
   262→    });
   263→    return parts.join('') + 'Z';
   264→  }).join('');
   265→}
   266→
   267→function getCentroid(rings) {
   268→  // Use first (outer) ring
   269→  const ring = rings[0];
   270→  let cx = 0, cy = 0;
   271→  for (const [lon, lat] of ring) {
   272→    cx += projectLon(lon);
   273→    cy += projectLat(lat);
   274→  }
   275→  return { x: Math.round(cx / ring.length * 100) / 100, y: Math.round(cy / ring.length * 100) / 100 };
   276→}
   277→
   278→// Bundesland iso code → DB code
   279→const BL_ISO_TO_DB = {
   280→  '1': '04', // Burgenland
   281→  '2': '08', // Kärnten
   282→  '3': '03', // Niederösterreich
   283→  '4': '05', // Oberösterreich
   284→  '5': '02', // Salzburg
   285→  '6': '06', // Steiermark
   286→  '7': '07', // Tirol
   287→  '8': '09', // Vorarlberg
   288→  '9': '01', // Wien
   289→};
   290→
   291→async function main() {
   292→  console.log('Fetching Bezirke GeoJSON...');
   293→  const response = await fetch(BEZIRKE_URL);
   294→  if (!response.ok) throw new Error(`HTTP ${response.status}`);
   295→  const geojson = await response.json();
   296→  console.log(`Got ${geojson.features.length} bezirk features`);
   297→
   298→  console.log('Fetching Bundesländer GeoJSON...');
   299→  const blResponse = await fetch(LAENDER_URL);
   300→  if (!blResponse.ok) throw new Error(`HTTP ${blResponse.status}`);
   301→  const blGeojson = await blResponse.json();
   302→  console.log(`Got ${blGeojson.features.length} bundesland features`);
   303→
   304→  // Group features by KFZ code (Wien 23 sub-districts → merge)
   305→  const byKfz = {};
   306→
   307→  for (const feature of geojson.features) {
   308→    const props = feature.properties;
   309→    // The GeoJSON uses 'iso' or 'id' for the district code
   310→    const gkz = String(props.iso || props.id || '');
   311→    const kfz = GKZ_TO_KFZ[gkz];
   312→    if (!kfz) {
   313→      console.warn(`  Unknown GKZ: ${gkz} (${props.name})`);
   314→      continue;
   315→    }
   316→    if (!byKfz[kfz]) byKfz[kfz] = [];
   317→
   318→    const geom = feature.geometry;
   319→    if (geom.type === 'Polygon') {
   320→      byKfz[kfz].push(geom.coordinates);
   321→    } else if (geom.type === 'MultiPolygon') {
   322→      for (const polygon of geom.coordinates) {
   323→        byKfz[kfz].push(polygon);
   324→      }
   325→    }
   326→  }
   327→
   328→  console.log(`Mapped to ${Object.keys(byKfz).length} Bezirke`);
   329→
   330→  // Build output
   331→  const entries = {};
   332→  for (const [kfz, polygons] of Object.entries(byKfz)) {
   333→    const meta = BEZIRK_META[kfz];
   334→    if (!meta) {
   335→      console.warn(`  No metadata for KFZ: ${kfz}`);
   336→      continue;
   337→    }
   338→
   339→    // Merge all rings into a single SVG path
   340→    const allRings = [];
   341→    const allOuterRings = [];
   342→    for (const polygon of polygons) {
   343→      for (const ring of polygon) {
   344→        allRings.push(ring);
   345→      }
   346→      allOuterRings.push(polygon[0]); // outer ring for centroid
   347→    }
   348→
   349→    const d = coordsToSvgPath(allRings);
   350→
   351→    // Centroid from all outer rings combined
   352→    let cx = 0, cy = 0, n = 0;
   353→    for (const ring of allOuterRings) {
   354→      for (const [lon, lat] of ring) {
   355→        cx += projectLon(lon);
   356→        cy += projectLat(lat);
   357→        n++;
   358→      }
   359→    }
   360→    cx = Math.round(cx / n * 100) / 100;
   361→    cy = Math.round(cy / n * 100) / 100;
   362→
   363→    entries[kfz] = {
   364→      d,
   365→      labelX: cx,
   366→      labelY: cy,
   367→      name: meta.name,
   368→      bundesland_code: meta.bundesland_code,
   369→    };
   370→  }
   371→
   372→  // Generate TypeScript output
   373→  const lines = [
   374→    '// Auto-generated by scripts/generate-bezirk-paths.mjs',
   375→    '// Source: github.com/ginseng666/GeoJSON-TopoJSON-Austria (CC BY-SA 3.0)',
   376→    '// Do not edit manually.',
   377→    '',
   378→    'export const BEZIRK_PATHS: Record<string, {',
   379→    '  d: string; labelX: number; labelY: number;',
   380→    '  name: string; bundesland_code: string;',
   381→    '}> = {',
   382→  ];
   383→
   384→  const sortedKeys = Object.keys(entries).sort((a, b) => {
   385→    const ba = entries[a].bundesland_code;
   386→    const bb = entries[b].bundesland_code;
   387→    if (ba !== bb) return ba.localeCompare(bb);
   388→    return a.localeCompare(b);
   389→  });
   390→
   391→  for (const kfz of sortedKeys) {
   392→    const e = entries[kfz];
   393→    lines.push(`  '${kfz}': {`);
   394→    lines.push(`    d: '${e.d}',`);
   395→    lines.push(`    labelX: ${e.labelX}, labelY: ${e.labelY},`);
   396→    lines.push(`    name: '${e.name.replace(/'/g, "\\'")}', bundesland_code: '${e.bundesland_code}',`);
   397→    lines.push(`  },`);
   398→  }
   399→
   400→  lines.push('};');
   401→  lines.push('');
   402→
   403→  // ─── Bundesländer borders (same projection) ───
   404→  const blEntries = {};
   405→  for (const feature of blGeojson.features) {
   406→    const props = feature.properties;
   407→    const iso = String(props.iso || props.id || '');
   408→    const dbCode = BL_ISO_TO_DB[iso];
   409→    if (!dbCode) {
   410→      console.warn(`  Unknown BL iso: ${iso} (${props.name})`);
   411→      continue;
   412→    }
   413→    const geom = feature.geometry;
   414→    const allRings = [];
   415→    if (geom.type === 'Polygon') {
   416→      for (const ring of geom.coordinates) allRings.push(ring);
   417→    } else if (geom.type === 'MultiPolygon') {
   418→      for (const polygon of geom.coordinates) {
   419→        for (const ring of polygon) allRings.push(ring);
   420→      }
   421→    }
   422→    blEntries[dbCode] = coordsToSvgPath(allRings);
   423→  }
   424→
   425→  lines.push('export const BL_BORDER_PATHS: Record<string, string> = {');
   426→  for (const code of Object.keys(blEntries).sort()) {
   427→    lines.push(`  '${code}': '${blEntries[code]}',`);
   428→  }
   429→  lines.push('};');
   430→  lines.push('');
   431→
   432→  const outPath = resolve(__dirname, '../client/src/data/bezirkPaths.ts');
   433→  writeFileSync(outPath, lines.join('\n'));
   434→  console.log(`Written ${sortedKeys.length} Bezirke + ${Object.keys(blEntries).length} BL borders to ${outPath}`);
   435→  console.log(`File size: ${(lines.join('\n').length / 1024).toFixed(1)} KB`);
   436→}
   437→
   438→main().catch(console.error);
   439→

