   237→//
   238→// X: x = lon * SX + OX
   239→//   SX = 78.55
   240→//   OX = 550 - 16.37 * 78.55 = -735.86
   241→//
   242→// Y: y = lat * SY + OY  (linear, negative because SVG Y increases downward)
   243→//   SY = -SX * 1.50 = -117.83  (Y/X ratio from existing map analysis)
   244→//   OY = 97 - 48.21 * (-117.83) = 97 + 5680.0 = 5777.0
   245→
   246→const SX = 78.55;
   247→const OX = -735.86;
   248→const SY = -117.83;
   249→const OY = 5777.0;
