   254→function coordsToSvgPath(rings) {
   255→  return rings.map((ring, ri) => {
   256→    const parts = ring.map(([lon, lat], i) => {
   257→      const x = projectLon(lon);
   258→      const y = projectLat(lat);
   259→      const xr = Math.round(x * 100) / 100;
   260→      const yr = Math.round(y * 100) / 100;
   261→      return `${i === 0 ? 'M' : 'L'}${xr},${yr}`;
   262→    });
   263→    return parts.join('') + 'Z';
   264→  }).join('');
