   266→
   267→function getCentroid(rings) {
   268→  // Use first (outer) ring
   269→  const ring = rings[0];
   270→  let cx = 0, cy = 0;
   271→  for (const [lon, lat] of ring) {
   272→    cx += projectLon(lon);
   273→    cy += projectLat(lat);
   274→  }
   275→  return { x: Math.round(cx / ring.length * 100) / 100, y: Math.round(cy / ring.length * 100) / 100 };
   276→}
