   307→  for (const feature of geojson.features) {
   308→    const props = feature.properties;
   309→    // The GeoJSON uses 'iso' or 'id' for the district code
   310→    const gkz = String(props.iso || props.id || '');
   311→    const kfz = GKZ_TO_KFZ[gkz];
   312→    if (!kfz) {
   313→      console.warn(`  Unknown GKZ: ${gkz} (${props.name})`);
   314→      continue;
   315→    }
   316→    if (!byKfz[kfz]) byKfz[kfz] = [];
   317→
   318→    const geom = feature.geometry;
   319→    if (geom.type === 'Polygon') {
   320→      byKfz[kfz].push(geom.coordinates);
   321→    } else if (geom.type === 'MultiPolygon') {
   322→      for (const polygon of geom.coordinates) {
   323→        byKfz[kfz].push(polygon);
   324→      }
   325→    }
   326→  }
   327→
   328→  console.log(`Mapped to ${Object.keys(byKfz).length} Bezirke`);
   329→
   330→  // Build output
   331→  const entries = {};
   332→  for (const [kfz, polygons] of Object.entries(byKfz)) {
   333→    const meta = BEZIRK_META[kfz];
   334→    if (!meta) {
   335→      console.warn(`  No metadata for KFZ: ${kfz}`);
   336→      continue;
   337→    }
   338→
   339→    // Merge all rings into a single SVG path
   340→    const allRings = [];
   341→    const allOuterRings = [];
   342→    for (const polygon of polygons) {
   343→      for (const ring of polygon) {
   344→        allRings.push(ring);
   345→      }
   346→      allOuterRings.push(polygon[0]); // outer ring for centroid
   347→    }
   348→
   349→    const d = coordsToSvgPath(allRings);
   350→
   351→    // Centroid from all outer rings combined
   352→    let cx = 0, cy = 0, n = 0;
   353→    for (const ring of allOuterRings) {
   354→      for (const [lon, lat] of ring) {
   355→        cx += projectLon(lon);
   356→        cy += projectLat(lat);
   357→        n++;
   358→      }
   359→    }
   360→    cx = Math.round(cx / n * 100) / 100;
   361→    cy = Math.round(cy / n * 100) / 100;
   362→
   363→    entries[kfz] = {
   364→      d,
   365→      labelX: cx,
   366→      labelY: cy,
   367→      name: meta.name,
   368→      bundesland_code: meta.bundesland_code,
   369→    };
   370→  }
   371→
   372→  // Generate TypeScript output
   373→  const lines = [
   374→    '// Auto-generated by scripts/generate-bezirk-paths.mjs',
   375→    '// Source: github.com/ginseng666/GeoJSON-TopoJSON-Austria (CC BY-SA 3.0)',
   376→    '// Do not edit manually.',
   377→    '',
   378→    'export const BEZIRK_PATHS: Record<string, {',
   379→    '  d: string; labelX: number; labelY: number;',
   380→    '  name: string; bundesland_code: string;',
   381→    '}> = {',
   382→  ];
   383→
   384→  const sortedKeys = Object.keys(entries).sort((a, b) => {
   385→    const ba = entries[a].bundesland_code;
   386→    const bb = entries[b].bundesland_code;
   387→    if (ba !== bb) return ba.localeCompare(bb);
   388→    return a.localeCompare(b);
   389→  });
   390→
   391→  for (const kfz of sortedKeys) {
   392→    const e = entries[kfz];
   393→    lines.push(`  '${kfz}': {`);
   394→    lines.push(`    d: '${e.d}',`);
   395→    lines.push(`    labelX: ${e.labelX}, labelY: ${e.labelY},`);
   396→    lines.push(`    name: '${e.name.replace(/'/g, "\\'")}', bundesland_code: '${e.bundesland_code}',`);
   397→    lines.push(`  },`);
   398→  }
   399→
   400→  lines.push('};');
   401→  lines.push('');
   402→
   403→  // ─── Bundesländer borders (same projection) ───
   404→  const blEntries = {};
   405→  for (const feature of blGeojson.features) {
   406→    const props = feature.properties;
   407→    const iso = String(props.iso || props.id || '');
   408→    const dbCode = BL_ISO_TO_DB[iso];
   409→    if (!dbCode) {
   410→      console.warn(`  Unknown BL iso: ${iso} (${props.name})`);
   411→      continue;
   412→    }
   413→    const geom = feature.geometry;
   414→    const allRings = [];
   415→    if (geom.type === 'Polygon') {
   416→      for (const ring of geom.coordinates) allRings.push(ring);
   417→    } else if (geom.type === 'MultiPolygon') {
   418→      for (const polygon of geom.coordinates) {
   419→        for (const ring of polygon) allRings.push(ring);
