  // Use first (outer) ring
  const ring = rings[0];
  let cx = 0, cy = 0;
  for (const [lon, lat] of ring) {
    cx += projectLon(lon);
    cy += projectLat(lat);
  }
  return { x: Math.round(cx / ring.length * 100) / 100, y: Math.round(cy / ring.length * 100) / 100 };
