  // Generate TypeScript output
  const lines = [
    '// Auto-generated by scripts/generate-bezirk-paths.mjs',
    '// Source: github.com/ginseng666/GeoJSON-TopoJSON-Austria (CC BY-SA 3.0)',
    '// Do not edit manually.',
